import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

depthwise_conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void depthwiseConv2dForwardKernel(const float* __restrict__ input,
                                             const float* __restrict__ weight,
                                             const float* __restrict__ bias,
                                             float* __restrict__ output,
                                             int N, int C, int H, int W,
                                             int kernel_size, int stride,
                                             int padding, int dilation,
                                             bool has_bias,
                                             int outH, int outW) {
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int bz = blockIdx.z;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int col = bx * blockDim.x + tx;
    int row = by * blockDim.y + ty;
    int batch_channel = bz;
    if (col < outW && row < outH) {
        int n = batch_channel / C;
        int c = batch_channel % C;
        float val = 0.0f;
        for(int k = 0; k < kernel_size; k++){
            int in_h = row * stride - padding + k * dilation;
            if(in_h >= 0 && in_h < H){
                val += input[((n * C + c) * H + in_h) * W + col] *
                       weight[((c * 1 + 0) * kernel_size + k) * 1 + 0];
            }
        }
        if(has_bias){
            val += bias[c];
        }
        output[((n * C + c) * outH + row) * outW + col] = val;
    }
}

torch::Tensor depthwise_conv2d_cuda(torch::Tensor input,
                                    torch::Tensor weight,
                                    torch::Tensor bias,
                                    int stride,
                                    int padding,
                                    int dilation,
                                    bool has_bias) {
    const auto N = input.size(0);
    const auto C = input.size(1);
    const auto H = input.size(2);
    const auto W = input.size(3);

    const auto kernel_size = weight.size(2);

    // Compute output spatial dimensions (floor division)
    int outH = (H + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int outW = (W + 2 * padding - dilation * (1 - 1) - 1) / stride + 1;

    auto output = torch::zeros({N, C, outH, outW}, input.options());
    const int total_bcz = N * C;

    dim3 block(16, 16);
    dim3 grid((outW + block.x - 1) / block.x,
              (outH + block.y - 1) / block.y,
              total_bcz);

    depthwiseConv2dForwardKernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        kernel_size, stride, padding, dilation,
        has_bias, outH, outW
    );

    return output;
}
""";

depthwise_conv2d_cpp = r"""
torch::Tensor depthwise_conv2d_cuda(torch::Tensor input,
                                    torch::Tensor weight,
                                    torch::Tensor bias,
                                    int stride,
                                    int padding,
                                    int dilation,
                                    bool has_bias);
"""

depthwise_conv2d = load_inline(
    name="depthwise_conv2d",
    cpp_sources=[depthwise_conv2d_cpp],
    cuda_sources=[depthwise_conv2d_source],
    functions=["depthwise_conv2d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.bias_flag = bias

        self.weight = nn.Parameter(torch.randn(in_channels, 1, kernel_size, 1))
        if bias:
            self.bias = nn.Parameter(torch.randn(in_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return depthwise_conv2d.depthwise_conv2d_cuda(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.zeros(0, device=x.device, dtype=x.dtype),
            self.stride,
            self.padding,
            self.dilation,
            self.bias is not None
        )
